//! 🧪️ Paged SQLite text retains the actual prefix after original receipt refusal.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetirementDemand};
use semio_framework_value::native_encoding::{NativeEncodeControl,NativeEncodeConstructionRecipient,NativeEncodeWorkRecipient};
struct Chunks(Vec<String>);impl Utf8Text for Chunks{fn text_bytes(&self)->usize{self.0.iter().map(String::len).sum()}fn text_chunk_count(&self)->usize{self.0.len()}fn text_chunk(&self,index:usize)->Option<&str>{self.0.get(index).map(String::as_str)}}
struct Recipient{grant:RetainedCloneGrant,refused:bool,received:RetainedCloneProgress}impl NativeEncodeConstructionRecipient for Recipient{fn submitted(&self)->RetainedCloneProgress{self.received}fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(self.grant)}fn accept(&mut self,grant:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{assert_eq!(grant,self.grant);self.received=self.received.checked_add(progress)?;if progress.copied_bytes==3&&!self.refused{self.refused=true;Err(ValueError::literal(ValueRefusalKind::WorkLimit,"paged text receipt refused"))}else{Ok(())}}}
fn close<T:semio_framework_value::retirement::RetireOwned>(value:T,grant:RetainedCloneGrant){let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(value).ok().unwrap();for _ in 0..4096{if owner.terminal_is_empty(){break}owner.step(grant).unwrap();}assert!(owner.terminal_is_empty());}
struct Loan(u64);impl NativeEncodeWorkRecipient for Loan{fn admits(&mut self,_:u64,more:u64)->Result<bool,ValueError>{Ok(more<=self.0)}fn committed(&mut self,actual:u64)->Result<(),ValueError>{self.0-=actual;Ok(())}}
#[test]fn paged_text_preserves_original_prefix_on_receipt_refusal(){
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(f["chunks"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().to_owned()).collect());assert_eq!(source.text_bytes(),f["bytes"].as_u64().unwrap()as usize);assert_eq!(serde_json::to_string(f["expected"].as_str().unwrap()).unwrap(),serde_json::to_string(&source.0.concat()).unwrap());
 let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let mut recipient=Recipient{grant,refused:false,received:Default::default()};let mut loan=Loan(1024);let mut native_progress=|_|true;let mut native=NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut native_progress);let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Encode(Default::default());
 let turn=native.with_construction_recipient(&mut recipient,|native|native.with_work_recipient(&mut loan,|native|{let mut owner=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut owner);Ok::<_,ValueError>(copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1))})).unwrap();
 assert!(recipient.refused);let failure=match turn.result{Err(error)=>error,Ok(())=>panic!("paged receipt unexpectedly accepted")};assert!(marker.performed);assert_eq!(output,f["refusedPrefix"].as_str().unwrap());assert_eq!(output.capacity(),f["bytes"].as_u64().unwrap()as usize);assert_eq!(recipient.received,RetainedCloneProgress{copied_items:3,copied_bytes:std::mem::size_of::<String>()+output.len(),retained_capacity_bytes:output.capacity(),released_bytes:0});assert_eq!(turn.work,Some(3));close(output,grant);close(failure,grant);
}

#[test]fn paged_text_prework_denial_keeps_native_ownership_empty(){
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(f["chunks"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().to_owned()).collect());let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let mut recipient=Recipient{grant,refused:false,received:Default::default()};let mut loan=Loan(f["deniedWork"].as_u64().unwrap());let mut native_progress=|_|true;let mut native=NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut native_progress);let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Encode(Default::default());
 let turn=native.with_construction_recipient(&mut recipient,|native|native.with_work_recipient(&mut loan,|native|{let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut original);Ok::<_,ValueError>(copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1))})).unwrap();
 let failure=match turn.result{Err(error)=>error,Ok(())=>panic!("paged work denial unexpectedly accepted")};assert_eq!(turn.work,Some(0));assert_eq!(native.owned_bytes(),0);assert_eq!(output.capacity(),0);assert!(!marker.performed);assert!(!recipient.refused);close(output,grant);close(failure,grant);
}

#[test]fn empty_paged_chunks_use_original_work_without_fabricated_backing(){
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(vec![String::new();f["emptyChunks"].as_u64().unwrap()as usize]);let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let mut recipient=Recipient{grant,refused:false,received:Default::default()};let mut loan=Loan(1024);let mut native_progress=|_|true;let mut native=NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut native_progress);let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Encode(Default::default());
 let turn=native.with_construction_recipient(&mut recipient,|native|native.with_work_recipient(&mut loan,|native|{let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut original);Ok::<_,ValueError>(copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1))})).unwrap();
 assert!(matches!(turn.result,Ok(())));assert_eq!(turn.work,Some(f["emptyWork"].as_u64().unwrap()));assert_eq!(output.capacity(),0);assert_eq!(recipient.received,RetainedCloneProgress::default());assert_eq!(native.owned_bytes(),0);close(output,grant);
}

#[test]fn paged_text_decode_direction_posts_exact_original_receipts(){
 use semio_framework_value_native_owned::native_decoding::{NativeDecodeControl,NativeDecodeConstructionRecipient,NativeDecodeWorkRecipient};
 struct DRecipient{grant:RetainedCloneGrant,received:RetainedCloneProgress}impl NativeDecodeConstructionRecipient for DRecipient{fn submitted(&self)->RetainedCloneProgress{self.received}fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(self.grant)}fn accept(&mut self,grant:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{assert_eq!(grant,self.grant);self.received=self.received.checked_add(progress)?;Ok(())}}
 struct DLoan(u64);impl NativeDecodeWorkRecipient for DLoan{fn admits(&mut self,observed:u64,more:u64)->Result<bool,ValueError>{Ok(observed.checked_add(more).is_some_and(|total|total<=self.0))}}
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(f["chunks"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().to_owned()).collect());let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let mut recipient=DRecipient{grant,received:Default::default()};let mut loan=DLoan(1024);let mut native_progress=|_|true;let mut native=NativeDecodeControl::new(grant.maximum_capacity_bytes,&mut native_progress);let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Decode(Default::default());
 let mut recipient_loan=semio_framework_value_native_owned::native_decoding::NativeConstructionRecipientLoan::new(&mut recipient);
 let turn=native.with_construction_recipient(&mut recipient_loan,|native|native.with_work_recipient(&mut loan,|native|{let mut original=semio_framework_io_control::NativeSnapshotDecodeOwner::new(native,grant);let mut owner=super::super::SnapshotOwner::Decode(&mut original);Ok::<_,ValueError>(copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1))})).unwrap();drop(recipient_loan);
 assert!(matches!(turn.result,Ok(())));assert_eq!(turn.work,Some(3));assert_eq!(output,f["expected"].as_str().unwrap());assert_eq!(recipient.received,RetainedCloneProgress{copied_items:3,copied_bytes:std::mem::size_of::<String>()+output.len(),retained_capacity_bytes:output.capacity(),released_bytes:0});assert_eq!(serde_json::to_string(&output).unwrap(),serde_json::to_string(f["expected"].as_str().unwrap()).unwrap());close(output,grant);
}

#[test]fn paged_source_unwind_retains_output_and_stage_receipt(){
 struct PanicChunks;impl Utf8Text for PanicChunks{fn text_bytes(&self)->usize{5}fn text_chunk_count(&self)->usize{2}fn text_chunk(&self,index:usize)->Option<&str>{if index==0{Some("ab")}else{panic!("paged fixture unwind")}}}
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=PanicChunks;let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};let mut recipient=Recipient{grant,refused:false,received:Default::default()};let mut loan=Loan(1024);let mut native_progress=|_|true;let mut native=NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut native_progress);let mut sql_progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_progress,Default::default());let initial=control.allocation_remaining_bytes();let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Encode(Default::default());
 let caught=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _=native.with_construction_recipient(&mut recipient,|native|native.with_work_recipient(&mut loan,|native|{let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut original);Ok::<_,ValueError>(copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1))}));}));
 assert!(caught.is_err());assert_eq!(output,f["unwindPrefix"].as_str().unwrap());assert_eq!(output.capacity(),f["bytes"].as_u64().unwrap() as usize);assert_eq!(initial-control.allocation_remaining_bytes(),output.capacity());let stage=stage_unwind.take().unwrap();assert!(stage.result.is_ok());assert_eq!(stage.work,Some(f["unwindWork"].as_u64().unwrap()));close(output,grant);close(stage,grant);
}

#[test]fn paged_text_wrong_allocation_direction_refuses_before_effect(){
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(vec!["x".into()]);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:64,maximum_release_bytes:64,maximum_depth:4};let mut progress=|_|true;let mut native=NativeEncodeControl::new(64,&mut progress);let mut sql=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Decode(Default::default());let mut stage_unwind=None;let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(&mut native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut original);
 let turn=copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1);let failure=match turn.result{Err(error)=>error,Ok(())=>panic!("wrong direction accepted")};assert_eq!(turn.work,Some(f["wrongDirectionWork"].as_u64().unwrap()));assert_eq!(output.capacity(),0);assert!(!marker.performed);drop(owner);drop(original);assert_eq!(native.owned_bytes(),0);let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};close(failure,close_grant);close(allocation,close_grant);
}

#[test]fn paged_text_unsettled_allocation_refuses_before_effect(){
 let f:serde_json::Value=serde_json::from_str(include_str!("📐️.json")).unwrap();let source=Chunks(Vec::new());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:64,maximum_release_bytes:64,maximum_depth:4};let mut progress=|_|true;let mut native=NativeEncodeControl::new(64,&mut progress);let mut sql=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql,Default::default());let mut output=String::new();let mut marker=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut state=semio_framework_io_control::NativeSnapshotEncodeAllocation::default();state.expected=Some(1);let mut allocation=semio_framework_io_control::NativeSnapshotAllocation::Encode(state);let mut stage_unwind=None;let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(&mut native,grant);let mut owner=super::super::SnapshotOwner::Encode(&mut original);
 let turn=copy_text_into(&source,&mut control,SqliteSnapshotPhase::ProjectSnapshot,&mut owner,&mut output,&mut marker,&mut unwind,&mut allocation,&mut stage_unwind,1);let failure=match turn.result{Err(error)=>error,Ok(())=>panic!("occupied allocation accepted")};assert_eq!(turn.work,Some(f["occupiedWork"].as_u64().unwrap()));assert!(allocation.is_unsettled());assert_eq!(output.capacity(),0);assert!(!marker.performed);drop(owner);drop(original);assert_eq!(native.owned_bytes(),0);let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};close(failure,close_grant);close(allocation,close_grant);
}
